DELETE FROM finances.stock_types
WHERE user_id = (SELECT id FROM system.users WHERE email = 'admin@admin.com')
AND name IN ('Ações', 'FII', 'ETF');

DELETE FROM finances.fund_types
WHERE user_id = (SELECT id FROM system.users WHERE email = 'admin@admin.com')
AND name IN ('Multimercado', 'Renda Fixa', 'Renda Variável');
